import{_ as e,o as a,c as o,a2 as d}from"./chunks/framework.BGlkWkwp.js";const p=JSON.parse('{"title":"AttributeList","description":"","frontmatter":{},"headers":[],"relativePath":"workbench/attribute-list.md","filePath":"workbench/attribute-list.md"}'),r={name:"workbench/attribute-list.md"};function i(n,t,s,h,c,l){return a(),o("div",null,[...t[0]||(t[0]=[d('<h1 id="attributelist" tabindex="-1">AttributeList <a class="header-anchor" href="#attributelist" aria-label="Permalink to &quot;AttributeList&quot;">​</a></h1><p>AttributeList is the list of the attributes of a thing: names and values that the user writes, read or changed where they stand.</p><h2 id="when-to-use" tabindex="-1">When to use <a class="header-anchor" href="#when-to-use" aria-label="Permalink to &quot;When to use&quot;">​</a></h2><p>Use it for the data that people attach to a thing by hand, such as a kind, a capacity or a note, in the attributes tab of an <a href="./inspector-frame">InspectorFrame</a>. It reaches the edges of its container, as a list does: put it in a <code>flush</code><a href="./inspector-section">InspectorSection</a> or straight in a panel&#39;s content. For settings the application defines, use a <a href="./field-list">FieldList</a>.</p><p>The application keeps the attributes. <code>items</code> is what the list shows, and every change is reported by the index in <code>items</code>; the application updates <code>items</code>, or the row goes back to what <code>items</code> holds. Names the user must see but not change (an identifier) go in <code>locked</code>; names the application keeps to itself go through <code>hide</code> and are not shown.</p><h2 id="props" tabindex="-1">Props <a class="header-anchor" href="#props" aria-label="Permalink to &quot;Props&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Prop</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>items</code></td><td>required</td><td>The attributes, <code>{ key, value }[]</code></td></tr><tr><td><code>onchange</code></td><td></td><td>Called with the index and the new <code>{ key, value }</code></td></tr><tr><td><code>onadd</code></td><td></td><td>Called with a new <code>{ key, value }</code>; shows the add action</td></tr><tr><td><code>onremove</code></td><td></td><td>Called with the index; shows the remove buttons</td></tr><tr><td><code>readonly</code></td><td><code>false</code></td><td>Only read: a <a href="./../components/kv">Kv</a></td></tr><tr><td><code>locked</code></td><td><code>[]</code></td><td>The names shown but not changed or removed</td></tr><tr><td><code>hide</code></td><td></td><td>Leaves out the attributes whose name it returns <code>true</code> for</td></tr></tbody></table><h2 id="contract" tabindex="-1">Contract <a class="header-anchor" href="#contract" aria-label="Permalink to &quot;Contract&quot;">​</a></h2><p>Read only, the list is a <a href="./../components/kv">Kv</a> in a <a href="./../components/block">Block</a>. Editable, each attribute is a row a button tall, and the rows touch, as list items do: the name in a column 7.5rem wide, the value, and at the end a small ghost button that removes it (named by the <code>removeAttribute</code> message). The name and the value are each an <a href="./../components/inline-edit">InlineEdit</a>: Enter commits, Escape restores, and an empty value shows the <code>addValue</code> action. A name cannot be emptied; the row goes back to it. A locked attribute is text only, with a muted lock at the end named by the <code>locked</code> message.</p><p>The add action is a <a href="./../components/link-action">LinkAction</a> in a Block after the rows. It opens a row of two small inputs, the name focused: Enter, or leaving the row, adds the attribute with its name and value trimmed; Escape, the cancel button or a row without a name drops it. Escape does not reach a panel or a modal around it. With no attribute to show, a Block says so (the <code>noAttributes</code> message). Below 24rem the value moves under the name.</p><h2 id="example" tabindex="-1">Example <a class="header-anchor" href="#example" aria-label="Permalink to &quot;Example&quot;">​</a></h2><figure class="kata-example"><iframe src="/kata/examples/attribute-list/" title="AttributeList" loading="lazy" style="width:100%;height:32rem;border:1px solid var(--vp-c-divider);border-radius:8px;"></iframe><figcaption><a href="/kata/examples/attribute-list/" target="_blank" rel="noopener">AttributeList</a></figcaption></figure>',12)])])}const m=e(r,[["render",i]]);export{p as __pageData,m as default};
